mapper.select:
        SELECT 
			count(*) 
		FROM 
			REP_REVEAL
		WHERE
			REPORT_NAME = #{reportName,jdbcType=VARCHAR}
		AND PRODID = #{prodId,jdbcType=VARCHAR}
		AND nvl2(TO_CHAR(START_DATE,'yyyy-mm-dd'),TO_CHAR(START_DATE,'yyyy-mm-dd'),'0') = #{reportDateBegin}
		AND nvl2(TO_CHAR(END_DATE,'yyyy-mm-dd'),TO_CHAR(END_DATE,'yyyy-mm-dd'),'0') = #{reportDateEnd}
		AND STATUS='E'

mapper.update:
    	UPDATE
   			REP_REVEAL
		SET STATUS = 'D'
			,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
			,UPDATE_TIME = sysdate
		WHERE
			REPORT_NAME = #{reportName,jdbcType=VARCHAR}
		AND PRODID = #{prodId,jdbcType=VARCHAR}
		AND nvl2(TO_CHAR(START_DATE,'yyyy-mm-dd'),TO_CHAR(START_DATE,'yyyy-mm-dd'),'0') = #{reportDateBegin}
		AND nvl2(TO_CHAR(END_DATE,'yyyy-mm-dd'),TO_CHAR(END_DATE,'yyyy-mm-dd'),'0') = #{reportDateEnd}
		AND STATUS='E'

