mapper.select:
SELECT T1.ID id, T1.PRODID prodid, T1.PROD_NAME prodName, T1.REPORT_CATEGORY reportCategory, T1.REPORT_NAME reportName, T1.IS_CONFIRM isConfirm, T1.IS_REVEAL isReveal, T1.START_DATE startDate, T1.END_DATE endDate, T1.REVEAL_CHANNEL revealChannel, T1.DETAIL detail, T1.REVEAL_END_DATE revealEndDate, T2.COMMENT_REMARK comment_remark, T1.FILEPATH filepath, T1.FILENAME filename, T1.WORKFLOW_ID workflowId FROM REP_REVEAL T1 left join REP_REVEAL_COMMENT T2 on T2.INFO_SEQNO = T1.ID
AND WORKFLOW_ID = #{workflowId,jdbcType=VARCHAR}
AND ID = #{seqno,jdbcType=VARCHAR}

		select s2.node_id from sys_wfl_business_list s1
        inner join sys_wfl_business_node s2 on s1.workflow_id = s2.workflow_id
        where s2.his_no='1' and s1.seq_no = #{seqNo,jdbcType=VARCHAR}

select deadline1.*
from(select rownum num, deadline.* from(
SELECT
A.BUSI_DATE busiDate,
A.MARKET_CODE marketCode,
A.IS_HOLIDAY isHoliday
FROM CHB_MKT_HOLIDAY A


		A.BUSI_DATE < to_date(#{holidayDate},'yyyy-MM-dd')


		A.BUSI_DATE > to_date(#{holidayDate},'yyyy-MM-dd')

	AND A.MARKET_CODE = #{marketCode,jdbcType=VARCHAR}
	AND A.IS_HOLIDAY = '0'


	order by A.BUSI_DATE desc


	order by A.BUSI_DATE asc

)deadline
)deadline1
where deadline1.num = #{days,jdbcType=INTEGER}
